import "./globals.css";
import type { Metadata } from "next";
import SiteHeader from "@/components/SiteHeader";

export const metadata: Metadata = {
  title: {
    default: "MemoriaMetal | Kişiye Özel Metal Baskı",
    template: "%s | MemoriaMetal",
  },
  description:
    "Fotoğraflarınızı kişiye özel, dayanıklı ve premium metal tablolara dönüştürün.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="tr">
      <body>
        <SiteHeader />
        {children}
      </body>
    </html>
  );
}